// work.action.complete — E5 AC1: the owner closes their action; a director or PM may close anyone's.
// Generated by `pnpm gen:command`; guard cases kept, acceptance cases added.
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { aStaffActor, countRows } from '@ocs/testing';
import { Conflict, Forbidden, NotFound, ValidationFailed } from '../../kernel/index.ts';
import { completeAction } from '../commands/complete-action.ts';
import { createAction } from '../commands/create-action.ts';
import { openWorkWorld, type WorkWorld } from './fixture.ts';

const pm = aStaffActor({ roles: ['pm'] });
const sales = aStaffActor({ roles: ['sales'] });
const otherSales = aStaffActor({ roles: ['sales'] });
const finance = aStaffActor({ roles: ['finance'] });
let w: WorkWorld;
const newAction = async (ownerId: string) =>
  (
    await w.t.kernel.execute(
      createAction,
      pm,
      {
        siteId: w.siteId,
        title: 'Book the installer',
        owner: { userId: ownerId },
        due: '2026-11-13',
        source: { kind: 'manual' },
      },
      'test',
    )
  ).id;
const isDone = (id: string) =>
  countRows(w.testDb.url, `action WHERE id = $1 AND status = 'done' AND done_at IS NOT NULL`, [id]);

beforeAll(async () => {
  w = await openWorkWorld();
  w.t.grant(pm, createAction.permission, completeAction.permission);
  w.t.grant(sales, completeAction.permission);
  w.t.grant(otherSales, completeAction.permission);
});

afterAll(async () => {
  await w.close();
});

describe('work.action.complete', () => {
  it('refuses an actor without the permission', async () => {
    const id = await newAction(finance.id);
    await expect(
      w.t.kernel.execute(completeAction, finance, { actionId: id }, 'test'),
    ).rejects.toBeInstanceOf(Forbidden);
  });

  it('refuses invalid input and an unknown action', async () => {
    await expect(w.t.kernel.execute(completeAction, pm, { actionId: 'x' }, 'test')).rejects.toBeInstanceOf(
      ValidationFailed,
    );
    await expect(
      w.t.kernel.execute(completeAction, pm, { actionId: randomUUID() }, 'test'),
    ).rejects.toBeInstanceOf(NotFound);
  });

  it('the owner closes their own action; someone else without director or PM role cannot', async () => {
    const id = await newAction(sales.id);
    await expect(
      w.t.kernel.execute(completeAction, otherSales, { actionId: id }, 'test'),
    ).rejects.toBeInstanceOf(Forbidden);
    expect(await isDone(id)).toBe(0);
    await w.t.kernel.execute(completeAction, sales, { actionId: id }, 'test');
    expect(await isDone(id)).toBe(1);
  });

  it("a PM closes anyone's action, once; each close is audited", async () => {
    const id = await newAction(otherSales.id);
    await w.t.kernel.execute(completeAction, pm, { actionId: id }, 'test');
    expect(await isDone(id)).toBe(1);
    await expect(w.t.kernel.execute(completeAction, pm, { actionId: id }, 'test')).rejects.toBeInstanceOf(
      Conflict,
    );
    expect(
      await countRows(w.testDb.url, `audit_event WHERE command = $1 AND object_id = $2`, [
        completeAction.name,
        id,
      ]),
    ).toBe(1);
  });
});
